const sources = [
  {
    name: 'contoh-portal',
    scrape_url: 'https://contoh-portal-loker.com/lowongan',
    // Tambahkan sumber lain di sini:
    // name: 'jobstreet', scrape_url: 'https://...'
  }
];

return sources.map(s => ({ json: s }));

// ============================================
// PARSER HTML → DATA LOWONGAN
// Sesuaikan selector CSS untuk setiap sumber
// ============================================

const cheerio = require('cheerio');
const html = $input.first().json.data;
const sourceName = $('Daftar Sumber Scraping').first().json.name;
const $ = cheerio.load(html);

const jobs = [];

// CONTOH SELECTOR - SESUAIKAN DENGAN PORTAL TARGET
// Ubah selector di bawah ini sesuai struktur HTML portal
$('.job-listing, .vacancy-item, article.job').each((i, el) => {
  const $el = $(el);

  const title = $el.find('.job-title, h2, h3').first().text().trim();
  const company = $el.find('.company-name, .employer').first().text().trim();
  const location = $el.find('.location, .job-location').first().text().trim();
  const sourceUrl = $el.find('a').first().attr('href') || '';

  // Skip jika data tidak lengkap
  if (!title || !company || !sourceUrl) return;

  // Pastikan URL absolut
  const fullUrl = sourceUrl.startsWith('http') 
    ? sourceUrl 
    : `https://contoh-portal-loker.com${sourceUrl}`;

  jobs.push({
    title,
    company,
    location: location || null,
    source_url: fullUrl,
    employment_type: null,
    salary_min: null,
    salary_max: null,
    description_raw: $el.find('.description, .job-desc').first().text().trim() || null,
    source_name: sourceName,
  });
});

if (jobs.length === 0) {
  throw new Error(`Tidak ada lowongan ditemukan dari ${sourceName}. Periksa selector CSS.`);
}

return jobs.map(j => ({ json: j }));

