// Parse AI response dan gabungkan dengan data loker

const items = $input.all();
const results = [];

for (const item of items) {
  const original = item.json;
  let summary = '';
  let tags = [];

  try {
    // Ambil content dari OpenRouter response
    const content = original.choices?.[0]?.message?.content || '';

    // Coba parse JSON
    let parsed = null;

    // Direct JSON
    try {
      parsed = JSON.parse(content);
    } catch (e) {
      // Coba extract JSON dari text
      const jsonMatch = content.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          parsed = JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
    }

    if (parsed) {
      summary = parsed.summary || '';
      tags = Array.isArray(parsed.tags) ? parsed.tags : [];
    } else {
      // Regex fallback
      const summaryMatch = content.match(/(?:summary|ringkasan)[:\s]*(.+?)(?=\n|tags|$)/is);
      if (summaryMatch) summary = summaryMatch[1].trim();

      const tagsMatch = content.match(/(?:tags|label)[:\s]*(.+?)$/is);
      if (tagsMatch) {
        tags = tagsMatch[1].split(',').map(t => t.trim().replace(/[\[\]"']/g, '')).filter(Boolean);
      }
    }
  } catch (e) {
    // Jika AI gagal total, lanjut tanpa enrichment
    summary = '';
    tags = [];
  }

  results.push({
    json: {
      title: original.title || $('Batch per 5 Item').item.json.title,
      company: original.company || $('Batch per 5 Item').item.json.company,
      location: original.location || $('Batch per 5 Item').item.json.location,
      source_url: original.source_url || $('Batch per 5 Item').item.json.source_url,
      employment_type: original.employment_type || null,
      salary_min: original.salary_min || null,
      salary_max: original.salary_max || null,
      description_raw: original.description_raw || null,
      summary_ai: summary,
      tags: tags,
      source_name: original.source_name || 'unknown',
    }
  });
}

return results;

// Kumpulkan semua hasil menjadi satu payload untuk ingest API

const items = $input.all();
const sourceName = items[0]?.json?.source_name || 'unknown';

const payload = {
  source: sourceName,
  scraped_at: new Date().toISOString(),
  jobs: items.map(item => ({
    title: item.json.title,
    company: item.json.company,
    location: item.json.location,
    employment_type: item.json.employment_type,
    salary_min: item.json.salary_min,
    salary_max: item.json.salary_max,
    description_raw: item.json.description_raw,
    summary_ai: item.json.summary_ai,
    tags: item.json.tags,
    source_url: item.json.source_url,
  }))
};

return [{ json: payload }];

// Log hasil ingest
const response = $input.first().json;

const summary = {
  status: 'SUCCESS',
  source: response.source || 'unknown',
  stats: response.stats || {},
  timestamp: new Date().toISOString(),
  message: `Ingest selesai: ${response.stats?.inserted || 0} baru, ${response.stats?.updated || 0} diupdate, ${response.stats?.skipped || 0} dilewati`
};

return [{ json: summary }];

